-- Catálogo de fases lunares del calendario agroecológico (SA-CU01).
--
-- Las fechas de corte de cada fase se calcularon con el algoritmo de fases lunares de
-- Jean Meeus (Astronomical Algorithms, capítulo 49), que reproduce la luna nueva de
-- referencia del 6 de enero de 2000 y el ciclo sinódico de 29,53 días. Cada período
-- cubre el rango completo de su fase, de modo que cualquier fecha consultada pertenece
-- a un solo período y los rangos no se traslapan.
--
-- Los nombres, las prácticas recomendadas y el consejo de Kinti siguen la cosmovisión
-- andina: la Killa es el mes lunar y Kinti es el guía que acompaña los trabajos del
-- huerto. Son orientativos y el Técnico MSP puede ajustarlos.

INSERT INTO calendario_lunar (fase_lunar, nombre_kichwa, nombre_espanol, fecha_inicio, fecha_fin,
                           practicas_recomendadas, consejo_kinti)
VALUES
('WINAK_KILLA_CRECIENTE', 'Wiñak Killa', 'Luna Creciente', '2026-01-01', '2026-01-02',
 'La savia de las plantas asciende con la luna creciente: es el mejor momento para sembrar hojas, flores y verduras medicinales, y para trasplantar.',
 'Kinti habla en la noche: la luna creciente llama a la semilla. Siembra al atardecer y riega con agua de lluvia o de manantial.'),
('PURA_KILLA_LLENA', 'Pura Killa', 'Luna Llena', '2026-01-03', '2026-01-10',
 'La planta alcanza su máximo de savia: cosecha raíces, tubérculos, hojas y flores medicinales. Es buen día para preparar infusiones y tinturas.',
 'Kinti habla en la noche: en la luna llena la planta guarda su medicina. Cosecha de madrugada, cuando el rocío todavía sostiene la hoja.'),
('WANUK_KILLA_MENGUANTE', 'Wañuk Killa', 'Luna Menguante', '2026-01-11', '2026-01-17',
 'La savia desciende a la raíz: siembra tubérculos y arros, toma esquejes para propagar y poda la copa para airear el huerto.',
 'Kinti habla en la noche: en la luna menguante todo baja a la raíz. Guarda las semillas y deja que la tierra recoja el descanso.'),
('YANA_KILLA_OSCURA', 'Yana Killa', 'Luna Nueva', '2026-01-18', '2026-01-24',
 'Tiempo de descanso de la tierra: limpiar malezas, preparar el suelo y podar los árboles frutales. No se recomienda la siembra.',
